mapper.update:
UPDATE animal SET animal_name = #{animalName}, type = #{type}, color = #{color},
  gender = #{gender}, location = #{location}, health = #{health}, remark = #{remark}
WHERE animal_id = #{animalId}

mapper.select:
SELECT r.*, a.animal_name, a.type AS animal_type, pu.nickname AS publisher_name, du.nickname AS dealer_name FROM rescue_order r LEFT JOIN animal a ON r.animal_id = a.animal_id LEFT JOIN `user` pu ON r.publish_user = pu.user_id LEFT JOIN `user` du ON r.deal_user = du.user_id
r.order_status IN ('处理中', '救助中') r.order_status = #{status}
ORDER BY r.create_time DESC, r.rescue_id DESC

mapper.update:
UPDATE feed_point SET point_name = #{pointName}, location = #{location}, food_status = #{foodStatus},
  last_update_user = #{lastUpdateUser}, update_time = #{updateTime}
WHERE point_id = #{pointId}
